use strict;
use warnings;
use File::Find;
use File::Slurp;

my $REPO = "/bench/repo";

sub get_go_files {
    my ($root, $exclude_test) = @_;
    my @files;
    find(sub {
        return if $_ eq "vendor" || $_ eq ".git";
        push @files, $File::Find::name if /\.go$/ && (!$exclude_test || !/_test\.go$/);
    }, $root);
    return @files;
}

my @internal_files = get_go_files("$REPO/internal", 0);
my @all_files = get_go_files($REPO, 0);

my @decls;
for my $fpath (@internal_files) {
    my $content = read_file($fpath);
    my ($pkg) = $content =~ /^package\s+(\w+)/m;
    $pkg //= "unknown";
    my $rel = $fpath; $rel =~ s/^\Q$REPO\E\/?//;

    while ($content =~ /^func\s+(?:\(([^)]+)\)\s+)?(\w+)\s*\(/gm) {
        my ($recv, $name) = ($1, $2);
        my $recv_type;
        if ($recv) {
            my @parts = split /\s+/, $recv;
            $recv_type = $parts[-1];
            $recv_type =~ s/^\*//;
        }
        push @decls, { name => $name, recv => $recv_type, file => $rel, fpath => $fpath, pkg => $pkg };
    }
}

print "Total declarations: ", scalar(@decls), "\n";

my @results;
for my $d (@decls) {
    my $name = $d->{name};
    my $count = 0;
    my %callers;

    for my $fpath (@all_files) {
        my $content = read_file($fpath);
        if ($d->{recv}) {
            my $pat = qr/\.$name\s*\(/;
            while ($content =~ /$pat/g) {
                my $pos = pos($content) - length($&);
                my $prefix = substr($content, ($pos > 30 ? $pos - 30 : 0), 30);
                next if $fpath eq $d->{fpath} && $prefix =~ /func\s/;
                $count++;
                my $rel = $fpath; $rel =~ s/^\Q$REPO\E\/?//;
                $callers{$rel} = 1;
            }
        } else {
            my $pat = qr/(?<![\w])$name\s*\(/;
            while ($content =~ /$pat/g) {
                my $pos = pos($content) - length($&);
                my $prefix = substr($content, ($pos > 30 ? $pos - 30 : 0), 30);
                next if $prefix =~ /func\s/;
                $count++;
                my $rel = $fpath; $rel =~ s/^\Q$REPO\E\/?//;
                $callers{$rel} = 1;
            }
        }
    }
    push @results, { %$d, count => $count, ncallers => scalar(keys %callers) };
}

@results = sort { $b->{count} <=> $a->{count} } @results;

print "\nTop 40:\n";
for my $r (@results[0..39]) {
    my $sym = $r->{recv} ? "($r->{recv}).$r->{name}" : $r->{name};
    printf "  %4d  callers=%3d  %-40s  %s\n", $r->{count}, $r->{ncallers}, $sym, $r->{file};
}
'

