BEGIN {
  repo = "/bench/repo"
}

function read_file(path,    cmd, line) {
  delete content
  n = 0
  while ((getline line < path) > 0) {
    content[n++] = line
  }
  close(path)
  return n
}

function join_content(n,    i, s) {
  s = ""
  for (i = 0; i < n; i++) s = s content[i] "\n"
  return s
}

END {
  # Process declarations
  cmd = "find " repo "/internal -name \"*.go\" | sort"
  while ((cmd | getline fpath) > 0) {
    n = read_file(fpath)
    rel = fpath
    sub("^" repo "/?", "", rel)
    for (i = 0; i < n; i++) {
      line = content[i]
      if (match(line, /^func \(([^)]+)\) ([A-Za-z_][A-Za-z0-9_]*)\(/, m)) {
        recv = m[1]
        name = m[2]
        split(recv, parts, " ")
        rt = parts[length(parts)]
        gsub(/^\*/, "", rt)
        key = "M:" rt ":" name
        decl_file[key] = rel
        decl_name[key] = name
        decl_recv[key] = rt
        decl_type[key] = "method"
      } else if (match(line, /^func ([A-Za-z_][A-Za-z0-9_]*)\(/, m)) {
        name = m[1]
        key = "F:" name
        decl_file[key] = rel
        decl_name[key] = name
        decl_type[key] = "func"
      }
    }
  }
  close(cmd)

  ndecl = 0
  for (k in decl_file) keys[ndecl++] = k

  # Count calls in all go files
  cmd = "find " repo " -name \"*.go\" ! -path \"*/vendor/*\" ! -path \"*/.git/*\" | sort"
  while ((cmd | getline fpath) > 0) {
    n = read_file(fpath)
    text = join_content(n)
    for (i = 0; i < ndecl; i++) {
      k = keys[i]
      name = decl_name[k]
      if (decl_type[k] == "method") {
        pat = "\\." name "[[:space:]]*\\("
        cnt = 0
        pos = 1
        while (match(substr(text, pos), pat)) {
          cnt++
          pos += RSTART + RLENGTH - 1
        }
        # subtract declarations in declaring file
        if (index(fpath, decl_file[k]) > 0) {
          for (j = 0; j < n; j++) {
            if (match(content[j], "^func \\([^)]*\\) " name "\\(")) cnt--
          }
        }
      } else {
        pat = "(^|[^A-Za-z0-9_])" name "[[:space:]]*\\("
        cnt = 0
        pos = 1
        while (match(substr(text, pos), pat)) {
          cnt++
          pos += RSTART + RLENGTH - 1
        }
        for (j = 0; j < n; j++) {
          if (match(content[j], "^func " name "\\(")) cnt--
        }
      }
      counts[k] += cnt
    }
  }
  close(cmd)

  # Output sorted
  for (k in counts) print counts[k], k, decl_file[k], decl_name[k], decl_recv[k]
}
